     7	import java.time.YearMonth;
     8	import java.time.format.DateTimeParseException;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	import java.util.function.Predicate;
    12	
    13	/** Relatório de reservas que começam em um mês. */
    14	public abstract class MonthlyReport<T> extends Report<YearMonth, T> {
    15	    protected static final Comparator<Reservation> BY_CHECK_IN_THEN_ID =
    16	            Comparator.comparing(Reservation::getCheckIn).thenComparing(Reservation::getId);
    17	
    18	    protected final ReservationService reservations;
    19	
    20	    protected MonthlyReport(ReservationService reservations) {
    21	        this.reservations = reservations;
    22	    }
    23	
    24	    @Override
    25	    public String paramName() { return "month"; }
    26	
    27	    @Override
    28	    protected YearMonth parse(String raw) {
    29	        try {
    30	            if (raw == null || !raw.matches("\\d{4}-\\d{2}")) throw new DateTimeParseException("", "", 0);
    31	            return YearMonth.parse(raw);
    32	        } catch (DateTimeParseException e) {
    33	            throw ApiException.invalid("Mês inválido, use o formato 2027-07");
    34	        }
    35	    }
    36	
    37	    protected List<Reservation> startingIn(YearMonth month, Predicate<Reservation> filter) {
    38	        return reservations.select(r -> YearMonth.from(r.getCheckIn()).equals(month) && filter.test(r))
    39	                .stream().sorted(BY_CHECK_IN_THEN_ID).toList();
    40	    }
    41	
    42	    /** As reservas que deixaram dinheiro com a pousada. */
    43	    protected List<Reservation> retainingMoney(YearMonth month) {
    44	        return startingIn(month, r -> r.retained().signum() > 0);
    45	    }
    46	}
