    10	import java.util.Comparator;
    11	import java.util.List;
    12	
    13	public class OccupancyReport extends Report<LocalDate, Reservation> {
    14	    private final ReservationService reservations;
    15	    private final Rooms rooms;
    16	
    17	    public OccupancyReport(ReservationService reservations, Rooms rooms) {
    18	        this.reservations = reservations;
    19	        this.rooms = rooms;
    20	    }
    21	
    22	    @Override
    23	    public String name() { return "occupancy"; }
    24	
    25	    @Override
    26	    public String paramName() { return "date"; }
    27	
    28	    @Override
    29	    protected LocalDate parse(String raw) {
    30	        try {
    31	            if (raw == null) throw new DateTimeParseException("", "", 0);
    32	            return LocalDate.parse(raw);
    33	        } catch (DateTimeParseException e) {
    34	            throw ApiException.invalid("Data inválida, use o formato 2027-07-10");
    35	        }
    36	    }
    37	
    38	    @Override
    39	    protected List<String> columns() {
    40	        return List.of("room", "type", "reservation", "check_in", "check_out");
    41	    }
    42	
    43	    @Override
    44	    protected List<Reservation> select(LocalDate night) {
    45	        return reservations.select(r -> r.getStatus().isPaid() && r.occupiesNight(night)).stream()
    46	                .sorted(Comparator.comparing(Reservation::getRoomNumber)).toList();
    47	    }
    48	
    49	    @Override
    50	    protected List<String> cells(Reservation r) {
    51	        return List.of(String.valueOf(r.getRoomNumber()), r.room().type().name(), String.valueOf(r.getId()),
    52	                r.getCheckIn().toString(), r.getCheckOut().toString());
    53	    }
    54	
    55	    @Override
    56	    protected List<String> total(LocalDate night, List<Reservation> items) {
    57	        long occupied = items.stream().map(Reservation::getRoomNumber).distinct().count();
    58	        return List.of("total", occupied + "/" + rooms.all().size());
    59	    }
    60	}
