     1	package br.com.marealta.reports;
     2	
     3	import br.com.marealta.Money;
     4	import br.com.marealta.RatePlan;
     5	import br.com.marealta.Reservation;
     6	import br.com.marealta.ReservationService;
     7	
     8	import java.math.BigDecimal;
     9	import java.time.YearMonth;
    10	import java.util.Arrays;
    11	import java.util.List;
    12	
    13	public class RatePlanReport extends MonthlyReport<RatePlanReport.Line> {
    14	    public record Line(RatePlan plan, long count, BigDecimal amount) {}
    15	
    16	    public RatePlanReport(ReservationService reservations) {
    17	        super(reservations);
    18	    }
    19	
    20	    @Override
    21	    public String name() { return "rate-plans"; }
    22	
    23	    @Override
    24	    protected List<String> columns() {
    25	        return List.of("rate_plan", "reservations", "amount");
    26	    }
    27	
    28	    @Override
    29	    protected List<Line> select(YearMonth month) {
    30	        List<Reservation> counted = retainingMoney(month);
    31	        return Arrays.stream(RatePlan.values()).map(plan -> {
    32	            List<Reservation> ofPlan = counted.stream().filter(r -> r.getRatePlan() == plan).toList();
    33	            BigDecimal amount = ofPlan.stream().map(Reservation::retained).reduce(Money.ZERO, BigDecimal::add);
    34	            return new Line(plan, ofPlan.size(), amount);
    35	        }).toList();
    36	    }
    37	
    38	    @Override
    39	    protected List<String> cells(Line line) {
    40	        return List.of(line.plan().name(), String.valueOf(line.count()), Money.csv(line.amount()));
    41	    }
    42	
    43	    @Override
    44	    protected List<String> total(YearMonth month, List<Line> lines) {
    45	        long count = lines.stream().mapToLong(Line::count).sum();
    46	        BigDecimal amount = lines.stream().map(Line::amount).reduce(Money.ZERO, BigDecimal::add);
    47	        return List.of("total", String.valueOf(count), Money.csv(amount));
    48	    }
    49	}
