     1	package br.com.marealta.reports;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/**
     7	 * Esqueleto de todo relatório CSV: título, cabeçalho, linhas, total.
     8	 * Cada relatório define só o que é dele; qualquer mudança comum a todos (como uma linha final
     9	 * com a data de emissão) entra em {@link #render}.
    10	 *
    11	 * @param <P> o período pedido (uma noite, um mês)
    12	 * @param <T> o item que vira uma linha
    13	 */
    14	public abstract class Report<P, T> {
    15	    private static final String INN = "Pousada Maré Alta";
    16	
    17	    public abstract String name();
    18	
    19	    /** Nome do parâmetro de consulta que traz o período. */
    20	    public abstract String paramName();
    21	
    22	    protected abstract P parse(String raw);
    23	
    24	    protected abstract List<String> columns();
    25	
    26	    protected abstract List<T> select(P period);
    27	
    28	    protected abstract List<String> cells(T item);
    29	
    30	    protected abstract List<String> total(P period, List<T> items);
    31	
    32	    public final String render(String rawPeriod) {
    33	        P period = parse(rawPeriod);
    34	        List<T> items = select(period);
    35	        List<String> lines = new ArrayList<>();
    36	        lines.add(String.join(",", INN, name(), period.toString()));
    37	        lines.add(String.join(",", columns()));
    38	        items.forEach(item -> lines.add(String.join(",", cells(item))));
    39	        lines.add(String.join(",", total(period, items)));
    40	        return String.join("\n", lines) + "\n";
    41	    }
    42	}
