    67	        }
    68	        if (body == null || !body.isObject()) {
    69	            throw ApiException.invalid("Corpo deve ser um objeto JSON");
    70	        }
    71	        int roomNumber = integer(body, "roomNumber");
    72	        String name = text(body, "guestName");
    73	        String email = text(body, "guestEmail");
    74	        String cpf = text(body, "guestCpf");
    75	        LocalDate checkIn = date(body, "checkIn");
    76	        LocalDate checkOut = date(body, "checkOut");
    77	        int guests = integer(body, "guests");
    78	        RatePlan plan = ratePlan(body);
    79	        if (!checkOut.isAfter(checkIn)) {
