    10	    private Pricing() {}
    11	
    12	    public static boolean isHighSeason(LocalDate night) {
    13	        Month month = night.getMonth();
    14	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    15	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    16	    }
