    18	    public static BigDecimal nightPrice(RoomType type, LocalDate night) {
    19	        BigDecimal rate = type.nightlyRate();
    20	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : rate;
    21	    }
    22	
    23	    public static BigDecimal subtotal(RoomType type, LocalDate checkIn, LocalDate checkOut) {
    24	        BigDecimal sum = Money.ZERO;
    25	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    26	            sum = sum.add(nightPrice(type, night));
    27	        }
    28	        return sum;
    29	    }
