    42	    private Optional<Reservation> find(String id) {
    43	        try {
    44	            long number = Long.parseLong(id);
    45	            return reservations.stream().filter(r -> r.getId() == number).findFirst();
    46	        } catch (NumberFormatException e) {
    47	            return Optional.empty();
    48	        }
    49	    }
