    19	    public synchronized Reservation create(int roomNumber, String name, String email, String cpf,
    20	                                           LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan) {
    21	        Room room = rooms.find(roomNumber)
    22	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + roomNumber + " não existe"));
    23	        if (guests > room.type().capacity()) {
    24	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    25	                    "O quarto " + roomNumber + " comporta no máximo " + room.type().capacity() + " hóspedes");
    26	        }
    27	        boolean taken = reservations.stream().anyMatch(r -> r.getRoomNumber() == roomNumber
    28	                && r.getStatus() != ReservationStatus.CANCELLED && r.overlaps(checkIn, checkOut));
    29	        if (taken) {
    30	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    31	        }
    32	        Reservation reservation = new Reservation(reservations.size() + 1L, room, name, email, cpf,
    33	                checkIn, checkOut, guests, plan);
    34	        reservations.add(reservation);
    35	        return reservation;
    36	    }
